 db.events.forEach(e=>{const example=def.events.find(x=>x.id===e.id);e.city??=example?.city||'Ciudad de México';e.functionMode??=example?.functionMode||'fixed';e.openStart??=example?.openStart||'';e.openEnd??=example?.openEnd||'';e.openDays??=example?.openDays||[0,1,2,3,4,5,6];e.openTime??=example?.openTime||'10:00';e.heroPosition??=example?.heroPosition||'center 40%';e.openSchedule??=example?.openSchedule||{};e.blockedDates??=[];e.deliveryOptions??=['digital','fisica','recogida'];e.shippingFee??=100;if(e.id==='matilda'||e.id==='nocturno'){if(e.functionMode!=='open'){e.functionMode='open';e.openStart=example?.openStart;e.openEnd=example?.openEnd;e.openDays=example?.openDays;e.openTime=example?.openTime;}e.openSchedule=example?.openSchedule||{};}if(!e.trailer)e.trailer='assets/tadaa-video-demo.mp4';});
 if(!db.events.some(e=>e.id==='nocturno'))db.events.unshift(def.events.find(e=>e.id==='nocturno'));
