// Los errores se presentan en rojo dentro del mismo paso; nunca dependen de un toast flotante.
const REG_EMAIL=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
function showRegistrationErrors(form,problems){
 form.querySelectorAll('.form-errors-summary,.field-error').forEach(n=>n.remove());
 form.querySelectorAll('[aria-invalid]').forEach(n=>{n.removeAttribute('aria-invalid');n.classList.remove('input-invalid')});
 const entries=Object.entries(problems).filter(([,message])=>!!message);
 if(!entries.length)return false;
 const summary=document.createElement('div');summary.className='form-errors-summary full';summary.setAttribute('role','alert');summary.textContent='Revisa los campos señalados en rojo para continuar.';form.prepend(summary);
 for(const [key,message] of entries){const el=[...form.elements].find(x=>x.name===key);if(!el)continue;el.setAttribute('aria-invalid','true');el.classList.add('input-invalid');const field=el.closest('.field')||el.parentElement;const hint=document.createElement('small');hint.className='field-error';hint.setAttribute('role','alert');hint.textContent=message;field?.appendChild(hint)}
 const first=[...form.elements].find(el=>el.getAttribute('aria-invalid')==='true');if(first){first.focus();first.scrollIntoView({behavior:'smooth',block:'center'})}
 return true;
}
function submitIdentity(form){
 const f=new FormData(form),givenNames=String(f.get('givenNames')||'').trim().replace(/\s+/g,' '),paternalSurname=String(f.get('paternalSurname')||'').trim().replace(/\s+/g,' '),maternalSurname=String(f.get('maternalSurname')||'').trim().replace(/\s+/g,' '),email=String(f.get('email')||'').trim().toLowerCase(),phone=String(f.get('phone')||'').trim(),memberId=String(f.get('memberId')||'').trim().toUpperCase(),institutionId=String(f.get('institutionId')||'');
 const issues={};
 const validName=v=>/^[\p{L}\p{M}][\p{L}\p{M} .'-]{1,}$/u.test(v);
 if(!validName(givenNames))issues.givenNames='Ingresa tu nombre o nombres (mínimo 2 caracteres).';
 if(!validName(paternalSurname))issues.paternalSurname='Ingresa un apellido paterno válido.';
 if(!validName(maternalSurname))issues.maternalSurname='Ingresa un apellido materno válido.';
 if(!REG_EMAIL.test(email))issues.email='Ingresa un correo electrónico válido, por ejemplo nombre@correo.com.';
 if(!/^[0-9]{10}$/.test(phone))issues.phone='Ingresa exactamente 10 dígitos, sin +52, espacios ni guiones.';
 if(!institutionId||!db.institutions.some(i=>i.active&&i.id===institutionId))issues.institutionId='Selecciona tu empresa o institución afiliada.';
 if(!memberId)issues.memberId='Introduce tu número de empleado o matrícula.';
 if(Object.keys(issues).length){showRegistrationErrors(form,issues);return}
 if(db.users.some(u=>String(u.email).toLowerCase()===email))issues.email='Este correo ya está registrado. Inicia sesión o utiliza otro.';
 if(db.users.some(u=>u.phone===phone))issues.phone='Este número móvil ya está registrado. Inicia sesión o utiliza otro.';
 if(db.users.some(u=>u.institutionId===institutionId&&u.memberId===memberId))issues.memberId='Este identificador ya está vinculado a otra cuenta.';
 if(!db.members.some(m=>m.active&&m.institutionId===institutionId&&String(m.memberId).toUpperCase()===memberId))issues.memberId='No encontramos este ID en el convenio elegido. Revisa el número o contacta a tu institución.';
 if(Object.keys(issues).length){showRegistrationErrors(form,issues);return}
 ui.signup={name:[givenNames,paternalSurname,maternalSurname].join(' '),givenNames,paternalSurname,maternalSurname,email,phone,institutionId,memberId};ui.signupStep='otp';registrationStep();
}
function submitRegistrationOTP(form){const f=new FormData(form),problems={};if(String(f.get('emailCode')||'').trim()!=='123456')problems.emailCode='Código de correo incorrecto. En la demo utiliza 123456.';if(String(f.get('smsCode')||'').trim()!=='123456')problems.smsCode='Código de SMS incorrecto. En la demo utiliza 123456.';if(showRegistrationErrors(form,problems))return;ui.signup.contactsVerified=true;ui.signupStep='address';registrationStep()}
async function updatePostalField(value){if(!/^\d{5}$/.test(value)){ui.postalInfo=null;}else{ui.postalInfo=await postalLookup(value)}const st=$('regState'),mu=$('regMunicipality'),co=$('regColony');if(!st||!mu||!co)return;st.value=ui.postalInfo?.state||'CP no encontrado en catálogo demo';mu.value=ui.postalInfo?.municipality||'Sin datos';co.innerHTML=`<option value="">${ui.postalInfo?'Selecciona tu colonia':'Sin colonias para este CP en demo'}</option>`+(ui.postalInfo?.colonies||[]).map(x=>`<option value="${safe(x)}">${safe(x)}</option>`).join('');}
function submitRegistrationDetails(form){const f=new FormData(form),cp=String(f.get('postalCode')||'').trim(),colony=String(f.get('colony')||''),gender=String(f.get('gender')||''),dob=String(f.get('dob')||'');const birth=isoDay(dob),now=new Date(),age=birth?now.getFullYear()-birth.getFullYear()-(now.getMonth()<birth.getMonth()||(now.getMonth()===birth.getMonth()&&now.getDate()<birth.getDate())?1:0):-1;const problems={};
 if(!ui.signup.contactsVerified){ui.signupStep='otp';registrationStep();return}
 if(!/^[0-9]{5}$/.test(cp)||!ui.postalInfo)problems.postalCode='Utiliza un CP de demostración válido: 06700, 03810 o 03100.';
 if(!ui.postalInfo?.colonies?.includes(colony))problems.colony='Selecciona una colonia asociada al código postal.';
 if(!birth||age<18||birth>now)problems.dob='Indica una fecha de nacimiento válida. La demo es para mayores de 18 años.';
 if(!f.has('legalAccepted'))problems.legalAccepted='Debes aceptar los términos y reconocer el aviso de privacidad.';
 if(showRegistrationErrors(form,problems))return;
 const user={id:uid('USR'),...ui.signup,postalCode:cp,state:ui.postalInfo.state,municipality:ui.postalInfo.municipality,colony,gender,dob,marketing:f.has('marketing'),legalAcceptedAt:Date.now(),contactsVerified:true,createdAt:Date.now()};
 db.users.push(user);db.session={userId:user.id,loggedAt:Date.now()};db.profile={name:user.name,email:user.email,phone:user.phone,company:db.institutions.find(x=>x.id===user.institutionId)?.name||'',notifications:true};db.favorites=[];db.cart=[];
 if(!store()){db.users=db.users.filter(x=>x.id!==user.id);db.session=null;showRegistrationErrors(form,{postalCode:'El navegador no permitió guardar la cuenta de demostración. Prueba abrir el proyecto desde un servidor de pruebas.'});return}
 closeModal();ui.signup={};go('inicio');toast('¡Cuenta DEMO creada! Inicia sesión en este mismo navegador cuando la necesites.');
}
function openLogin(){ui.loginStep='email';ui.loginEmail='';renderLogin()}
function renderLogin(){showModal(`<div class="modal-header"><div><div class="eyebrow">TADAA! · MI CUENTA</div><h2>Bienvenido de vuelta.</h2></div><button class="modal-close" data-action="close-modal">×</button></div>${ui.loginStep==='email'?`<form id="loginEmailForm" class="form-grid"><div class="field full"><label>Correo personal registrado</label><input name="email" type="email" required class="form-input" placeholder="tu@correo.com"/></div><div class="field full"><button class="btn wide">Enviar código de acceso (demo)</button></div></form>`:`<p class="muted small">Verificación para <b>${safe(ui.loginEmail)}</b>. Código simulado: <b>123456</b>. No se envía correo real.</p><form id="loginOTPForm" class="form-grid"><div class="field full"><label>Código de acceso</label><input type="text" pattern="[0-9]{6}" maxlength="6" name="code" required class="form-input otp-input" placeholder="123456"/></div><div class="field full"><button class="btn wide">Entrar a mi cuenta</button></div></form>`}<p class="small muted">¿No tienes cuenta? <button class="inline-legal" data-action="register-open">Regístrate aquí</button></p>`)}
function submitLoginEmail(form){const email=String(new FormData(form).get('email')||'').trim().toLowerCase();if(!db.users.some(u=>u.email===email)){toast('Ese correo no tiene una cuenta en esta demostración.');return}ui.loginEmail=email;ui.loginStep='otp';renderLogin();}
function submitLoginOTP(form){if(String(new FormData(form).get('code'))!=='123456'){toast('Código incorrecto. Usa 123456 en la demo.');return}const user=db.users.find(u=>u.email===ui.loginEmail);if(!user)return;db.session={userId:user.id,loggedAt:Date.now()};db.profile={name:user.name,email:user.email,phone:user.phone,company:db.institutions.find(i=>i.id===user.institutionId)?.name||''};store();closeModal();go('inicio');toast('Sesión de demostración iniciada.');}
function legalPopup(which){const terms=which==='terms';const title=terms?'Términos y condiciones del servicio':'Aviso de privacidad — resumen de demostración';const content=terms?`<p>Esta maqueta no vende boletos ni constituye condiciones contractuales definitivas. Al usar la plataforma real, las solicitudes estarán sujetas a verificación de convenio, disponibilidad del proveedor y precio final confirmado por TADAA!.</p><p>La solicitud inicial no aparta localidades ni genera cargo. Tras autorizarse una compra, habrá hasta 8 horas para efectuar el pago; el proveedor puede modificar existencias. Las políticas de cambios, cancelaciones y reembolsos se mostrarán por producto y deberán respetar los derechos legales del consumidor.</p><p>Los pases provisionales y comprobantes de seguimiento no son boletos de acceso. La entrega oficial se determinará por evento y proveedor.</p>`:`<p>Este es un texto de muestra, no un aviso legal aprobado. TADAA! trataría datos de identidad, contacto, institución, identificador de afiliación, edad y domicilio de residencia para validar el acceso al convenio y gestionar pedidos.</p><p>El correo promocional se solicita por separado y es opcional. Los datos de facturación solo se recabarán al pedir un CFDI y las direcciones completas únicamente cuando se elija envío físico.</p><p>Antes de operar se publicará el aviso con identificación del responsable, finalidades, mecanismos ARCO, conservación de datos y procedimientos para retirar el consentimiento de marketing.</p>`;
 document.getElementById('legalLayer')?.remove();document.body.insertAdjacentHTML('beforeend',`<div id="legalLayer" class="legal-overlay"><div class="legal-content" role="dialog" aria-modal="true" aria-label="${safe(title)}"><div class="modal-header"><h2>${safe(title)}</h2><button class="modal-close" data-action="close-legal" aria-label="Cerrar">×</button></div>${content}<button class="btn" data-action="close-legal">Entendido</button></div></div>`);
}

function profileInitial(){return (currentUser()?.name||db.profile.name||'T').trim().slice(0,1).toUpperCase()}
function openDateModal(id){const e=eventBy(id);if(e.functionMode!=='open')return;ui.calendarMonth=(ui.openDate||e.openStart||new Date().toISOString().slice(0,10)).slice(0,7);showCalendar(e)}
function showCalendar(e){const month=ui.calendarMonth||e.openStart?.slice(0,7)||'2026-11',first=new Date(month+'-01T12:00:00');if(Number.isNaN(first.getTime()))return;const year=first.getFullYear(),mo=first.getMonth();const start=(first.getDay()+6)%7,days=new Date(year,mo+1,0).getDate();const header=new Intl.DateTimeFormat('es-MX',{month:'long',year:'numeric'}).format(first);const dateCells=[];for(let i=0;i<start;i++)dateCells.push('<span class="cal-empty"></span>');for(let n=1;n<=days;n++){const day=`${year}-${String(mo+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`;const dt=isoDay(day);const valid=day>=(e.openStart||'0000-01-01')&&day<=(e.openEnd||'9999-12-31')&&(e.openDays||[0,1,2,3,4,5,6]).includes(dt.getDay())&&!(e.blockedDates||[]).includes(day)&&day>=new Date().toISOString().slice(0,10);dateCells.push(`<button class="cal-day ${ui.openDate===day?'picked':''}" data-action="calendar-day" data-id="${safe(day)}" ${!valid?'disabled':''} title="${valid?'Disponible para consultar':'Fecha no habilitada'}">${n}${valid?'<i></i>':''}</button>`)}showModal(`<div class="modal-header"><div><div class="eyebrow">FUNCIONES ABIERTAS</div><h2 style="margin:7px 0 0">Elige tu día</h2></div><button class="modal-close" data-action="close-modal" aria-label="Cerrar">×</button></div><div class="cal-title"><button class="cal-arrow" data-action="calendar-prev" aria-label="Mes anterior">‹</button><strong>${safe(header)}</strong><button class="cal-arrow" data-action="calendar-next" aria-label="Mes siguiente">›</button></div><div class="calendar-grid">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<b class="weekday">${d}</b>`).join('')}${dateCells.join('')}</div><p class="small muted" style="margin:18px 0 0"><span class="lime-disc"></span> Días habilitados para solicitar disponibilidad. La fecha no garantiza acceso ni apartado.</p><p class="small muted">Horarios: ${safe(Object.entries(e.openSchedule||{}).map(([d,t])=>['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'][+d]+' '+t).join(' · ')||e.openTime||'Por confirmar')}</p>`)}
function stepCalendar(monthDelta){const [year,mo]=(ui.calendarMonth||'2026-11').split('-').map(Number);const next=new Date(year,mo-1+monthDelta,1);ui.calendarMonth=`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}`;showCalendar(selectedEvent())}
function addCartSelection(){const e=selectedEvent(),z=e.zones.find(x=>x.id===ui.selectedZone);const date=chosenFunction(e);if(!z||!date){toast('Selecciona una función o un día disponible antes de continuar.');if(e.functionMode==='open')openDateModal(e.id);return false}const key=e.id+'|'+date+'|'+z.id;const prev=db.cart.find(x=>x.key===key);if(prev){prev.qty=Math.min(8,prev.qty+ui.quantity)}else db.cart.push({id:uid('C'),key,eventId:e.id,function:date,zoneId:z.id,qty:ui.quantity,createdAt:Date.now()});store();renderHeader();toast('Selección añadida al carrito. Aún no hay boletos apartados.');return true}
function removeCartItem(id){db.cart=db.cart.filter(x=>x.id!==id);store();render()}
function cartRows(){return db.cart.map(x=>{const e=db.events.find(y=>y.id===x.eventId);if(!e)return null;const z=e.zones.find(y=>y.id===x.zoneId);if(!z||!z.active)return null;return {x,e,z}}).filter(Boolean)}
function submitCart(){if(!db.cart.length){toast('Tu carrito está vacío.');return}showModal(`<div class="modal-header"><div><div class="eyebrow">${db.cart.length} SELECCIONES</div><h2>Solicitar disponibilidad</h2></div><button class="modal-close" data-action="close-modal">×</button></div><div class="notice-box lime" style="margin-bottom:19px">Se generará una solicitud independiente por selección. No hay apartado ni pago en esta etapa.</div><form id="cartRequestForm">${customerFields()}</form>`)}
