 $('mobileNav').innerHTML=nav.map(([route,ico,t])=>`<button class="${ui.route===route?'active':''}" data-route="${route}">${icon(ico,21)}<span>${t}${route==='carrito'&&db.cart.length?' ('+db.cart.length+')':''}</span></button>`).join('');
